import sys,json
from pathlib import Path
source=Path(sys.argv[1]);sys.path[:0]=[str(source/'packages/friday-chat/src'),str(source/'packages/friday-commands/src')]
from friday_chat.commands.registry import CommandRegistry,CommandArgument
import friday_chat.commands.registry as module
assert Path(module.__file__).resolve().is_relative_to(source.resolve())
rows=[]
for label,value in [('False',False),('zero',0),('empty-string',''),('empty-list',[]),('integer',5),('list',['x']),('bytes',b'extra'),('valid-string','Extra detail.')]:
 registry=CommandRegistry();registry.register('report',description='Report.',category='custom',detail=value)
 for focus in [None,'report','unknown']:
  try: result={'output':registry.render_help(focus)}
  except Exception as error: result={'exception':type(error).__name__,'message':str(error)}
  rows.append({'case':'detail:'+label,'focus':focus,**result})
for field in ['name','description']:
 registry=CommandRegistry();kwargs={'name':'item','description':'Item.'};kwargs[field]=b'value'
 registry.register('report',description='Report.',category='custom',arguments=(CommandArgument(**kwargs),))
 for focus in [None,'report','unknown']:
  try: result={'output':registry.render_help(focus)}
  except Exception as error: result={'exception':type(error).__name__,'message':str(error)}
  rows.append({'case':'argument:'+field+':bytes','focus':focus,**result})
Path(sys.argv[2]).write_text(json.dumps({'origin':str(module.__file__),'rows':rows},indent=2)+'\n')
